import sys, json
for line in sys.stdin:
    try:
        obj = json.loads(line.strip())
        # print just the role and first 200 chars of content
        role = obj.get('role', 'unknown')
        if 'content' in obj:
            c = obj['content']
            if isinstance(c, str):
                print(f'[{role}]: {c[:300]}')
            elif isinstance(c, list):
                for part in c:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        print(f'[{role}]: {part[\"text\"][:300]}')
        elif 'text' in obj:
            print(f'[{role}]: {str(obj[\"text\"])[:300]}')
        else:
            print(f'[{role}]: {json.dumps(obj)[:200]}')
    except:
        pass
" 2>/dev/null | head -60

